import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'

import { businessKnowledgeSettingsRetrieve } from 'products/business_knowledge/frontend/generated/api'
import type { BusinessKnowledgeSettingsApi } from 'products/business_knowledge/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface supportTicketsBannerLogicValues {
    settings: BusinessKnowledgeSettingsApi | null
    settingsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface supportTicketsBannerLogicActions {
    loadSettings: () => any
    loadSettingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSettingsSuccess: (
        settings: BusinessKnowledgeSettingsApi | null,
        payload?: any
    ) => {
        settings: BusinessKnowledgeSettingsApi | null
        payload?: any
    }
}

export type supportTicketsBannerLogicType = MakeLogicType<
    supportTicketsBannerLogicValues,
    supportTicketsBannerLogicActions
>

// Reads the settings once. businessKnowledgeSettingsLogic polls while a backfill runs, which the banner does not need.
export const supportTicketsBannerLogic = kea<supportTicketsBannerLogicType>([
    path(['products', 'conversations', 'frontend', 'components', 'SupportTicketsBanner', 'supportTicketsBannerLogic']),
    loaders(() => ({
        settings: [
            null as BusinessKnowledgeSettingsApi | null,
            {
                loadSettings: async () => {
                    try {
                        return await businessKnowledgeSettingsRetrieve(String(ApiConfig.getCurrentTeamId()))
                    } catch {
                        return null
                    }
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadSettings()
    }),
])
